+@page "/book-appointment"
+@rendermode InteractiveServer
+@using sv_d7c1609a4f70441ca864cdf94f9d349c.Models
+@using sv_d7c1609a4f70441ca864cdf94f9d349c.Services
+@inject AppointmentService AppointmentSvc
+
+<PageTitle>Book Appointment</PageTitle>
+
+<h1>Book an Appointment</h1>
+
+@if (isSubmitted)
+{
+    <div class="alert alert-success mt-3">
+        <h4>Appointment Requested!</h4>
+        <p>Thank you, <strong>@model.PatientName</strong>. Your appointment with <strong>@model.Doctor</strong>
+           on <strong>@model.AppointmentDate?.ToString("MMMM d, yyyy")</strong> at <strong>@model.TimeSlot</strong>
+           has been submitted.</p>
+    </div>
+}
+else
+{
+    <EditForm Model="model" OnValidSubmit="HandleSubmit" FormName="appointment">
+        <DataAnnotationsValidator />
+
+        @* ───── STEP 1 ───── *@
+        <fieldset>
+            <legend>Patient Information</legend>
+
+            <div class="mb-3">
+                <label for="patientName" class="form-label">Patient Name</label>
+                <InputText id="patientName" class="form-control" @bind-Value="model.PatientName" />
+                <ValidationMessage For="() => model.PatientName" />
+            </div>
+
+            <div class="mb-3">
+                <label for="email" class="form-label">Email</label>
+                <InputText id="email" class="form-control" @bind-Value="model.Email" />
+                <ValidationMessage For="() => model.Email" />
+                @if (serverErrors.ContainsKey("Email"))
+                {
+                    <div class="validation-message">@serverErrors["Email"]</div>
+                }
+            </div>
+
+            <div class="mb-3">
+                <label for="phone" class="form-label">Phone</label>
+                <InputText id="phone" class="form-control" @bind-Value="model.Phone" />
+                <ValidationMessage For="() => model.Phone" />
+            </div>
+
+            <div class="mb-3">
+                <label for="insurance" class="form-label">Insurance Provider</label>
+                <InputSelect id="insurance" class="form-select" @bind-Value="model.InsuranceProvider">
+                    <option value="">-- Select --</option>
+                    <option value="Aetna">Aetna</option>
+                    <option value="BlueCross">BlueCross</option>
+                    <option value="Cigna">Cigna</option>
+                    <option value="UnitedHealth">UnitedHealth</option>
+                    <option value="None">None</option>
+                </InputSelect>
+                <ValidationMessage For="() => model.InsuranceProvider" />
+            </div>
+        </fieldset>
+
+        @if (!showStep2)
+        {
+            <button type="button" class="btn btn-primary" @onclick="ProceedToStep2">
+                Next
+            </button>
+        }
+
+        @* ───── STEP 2 ───── *@
+        @if (showStep2)
+        {
+            <fieldset class="mt-4">
+                <legend>Appointment Details</legend>
+
+                <div class="mb-3">
+                    <label for="doctor" class="form-label">Preferred Doctor</label>
+                    <InputSelect id="doctor" class="form-select" @bind-Value="model.Doctor"
+                                 @bind-Value:after="OnDoctorOrDateChanged">
+                        <option value="">-- Select --</option>
+                        @foreach (var doc in doctors)
+                        {
+                            <option value="@doc">@doc</option>
+                        }
+                    </InputSelect>
+                    <ValidationMessage For="() => model.Doctor" />
+                    @if (serverErrors.ContainsKey("Doctor"))
+                    {
+                        <div class="validation-message">@serverErrors["Doctor"]</div>
+                    }
+                </div>
+
+                <div class="mb-3">
+                    <label for="date" class="form-label">Date</label>
+                    <InputDate id="date" class="form-control" @bind-Value="model.AppointmentDate"
+                               @bind-Value:after="OnDoctorOrDateChanged" />
+                    <ValidationMessage For="() => model.AppointmentDate" />
+                    @if (model.AppointmentDate.HasValue && model.AppointmentDate.Value <= DateOnly.FromDateTime(DateTime.Today))
+                    {
+                        <div class="validation-message">Date must be in the future.</div>
+                    }
+                </div>
+
+                <div class="mb-3">
+                    <label for="timeSlot" class="form-label">Time Slot</label>
+                    <InputSelect id="timeSlot" class="form-select" @bind-Value="model.TimeSlot">
+                        <option value="">-- Select --</option>
+                        @foreach (var slot in timeSlots)
+                        {
+                            <option value="@slot">@slot</option>
+                        }
+                    </InputSelect>
+                    <ValidationMessage For="() => model.TimeSlot" />
+                    @if (serverErrors.ContainsKey("TimeSlot"))
+                    {
+                        <div class="validation-message">@serverErrors["TimeSlot"]</div>
+                    }
+                </div>
+
+                <div class="mb-3">
+                    <label for="reason" class="form-label">Reason for Visit</label>
+                    <InputTextArea id="reason" class="form-control" @bind-Value="model.Reason" rows="3" />
+                    <ValidationMessage For="() => model.Reason" />
+                    <small class="text-muted">@model.Reason.Length / 500</small>
+                </div>
+            </fieldset>
+
+            <div class="mt-3 d-flex gap-2">
+                <button type="button" class="btn btn-secondary" @onclick="BackToStep1">Back</button>
+                <button type="button" class="btn btn-info" @onclick="CheckAvailability" disabled="@isChecking">
+                    @(isChecking ? "Checking…" : "Check Availability")
+                </button>
+                <button type="submit" class="btn btn-success" disabled="@(!availabilityChecked || serverErrors.Count > 0)">
+                    Book Appointment
+                </button>
+            </div>
+        }
+    </EditForm>
+}
+
+@code {
+    private AppointmentModel model = new();
+    private bool showStep2;
+    private bool isSubmitted;
+    private bool isChecking;
+    private bool availabilityChecked;
+
+    private List<string> doctors = new();
+    private List<string> timeSlots = new();
+    private Dictionary<string, string> serverErrors = new();
+
+    protected override async Task OnInitializedAsync()
+    {
+        doctors = await AppointmentSvc.GetDoctorsAsync();
+    }
+
+    private void ProceedToStep2()
+    {
+        // Validate step 1 fields manually
+        if (string.IsNullOrWhiteSpace(model.PatientName)
+            || string.IsNullOrWhiteSpace(model.Email)
+            || string.IsNullOrWhiteSpace(model.Phone)
+            || string.IsNullOrWhiteSpace(model.InsuranceProvider))
+        {
+            return;
+        }
+
+        // Basic email format check
+        try
+        {
+            var addr = new System.Net.Mail.MailAddress(model.Email);
+            if (addr.Address != model.Email)
+                return;
+        }
+        catch
+        {
+            return;
+        }
+
+        showStep2 = true;
+    }
+
+    private void BackToStep1()
+    {
+        showStep2 = false;
+        serverErrors.Clear();
+        availabilityChecked = false;
+    }
+
+    private async Task OnDoctorOrDateChanged()
+    {
+        serverErrors.Clear();
+        availabilityChecked = false;
+        model.TimeSlot = "";
+
+        if (!string.IsNullOrEmpty(model.Doctor) && model.AppointmentDate.HasValue
+            && model.AppointmentDate.Value > DateOnly.FromDateTime(DateTime.Today))
+        {
+            timeSlots = await AppointmentSvc.GetAvailableTimeSlotsAsync(
+                model.Doctor, model.AppointmentDate.Value);
+        }
+        else
+        {
+            timeSlots = new();
+        }
+    }
+
+    private async Task CheckAvailability()
+    {
+        serverErrors.Clear();
+        availabilityChecked = false;
+
+        // Client-side gate: require step 2 fields filled and future date
+        if (string.IsNullOrWhiteSpace(model.Doctor)
+            || !model.AppointmentDate.HasValue
+            || model.AppointmentDate.Value <= DateOnly.FromDateTime(DateTime.Today)
+            || string.IsNullOrWhiteSpace(model.TimeSlot)
+            || string.IsNullOrWhiteSpace(model.Reason))
+        {
+            return;
+        }
+
+        isChecking = true;
+
+        serverErrors = await AppointmentSvc.ValidatePatientAsync(
+            model.Email, model.InsuranceProvider, model.Doctor, model.TimeSlot);
+
+        isChecking = false;
+
+        if (serverErrors.Count == 0)
+        {
+            availabilityChecked = true;
+        }
+    }
+
+    private void HandleSubmit()
+    {
+        if (!availabilityChecked || serverErrors.Count > 0)
+            return;
+
+        isSubmitted = true;
+    }
+}
+

